-- Replace only the DOCUMENT_VERSION model pair predicate in the existing summary-subject CHECK.
-- Exact available catalog pairs; SQL NULL remains the official producer path.
BEGIN;
ALTER TABLE action_attempt
  DROP CONSTRAINT ck_action_attempt_summary_subject,
  ADD CONSTRAINT ck_action_attempt_summary_subject CHECK (subject_kind::text = 'WORK_ITEM'::text AND work_item_id IS NOT NULL AND matter_id IS NULL AND matter_revision_id IS NULL AND (action_type::text <> ALL (ARRAY['OPENCLAW_MATTER_ASSESSMENT'::character varying::text, 'DOCUMENT_TRANSLATE'::character varying::text])) OR subject_kind::text = 'ENGINEERING_MATTER'::text AND work_item_id IS NULL AND document_version_id IS NULL AND matter_id IS NOT NULL AND matter_revision_id IS NOT NULL AND action_type::text = 'OPENCLAW_MATTER_ASSESSMENT'::text AND input_revision IS NOT NULL AND base_revision IS NOT NULL OR subject_kind::text = 'DOCUMENT_VERSION'::text AND work_item_id IS NULL AND matter_id IS NULL AND matter_revision_id IS NULL AND document_version_id IS NOT NULL AND producer_run_id IS NOT NULL AND input_revision IS NOT NULL AND input_revision > 0 AND action_type::text = 'DOCUMENT_TRANSLATE'::text AND (execution_model_json IS NULL OR jsonb_typeof(execution_model_json::jsonb) = 'object'::text AND jsonb_exists_all(execution_model_json::jsonb, ARRAY['modelRef'::text, 'displayName'::text, 'providerKind'::text, 'settingsRevision'::text, 'selectedAt'::text]) AND (((execution_model_json::jsonb ->> 'modelRef'::text, execution_model_json::jsonb ->> 'providerKind'::text) IN (('miaoda/minimax-m3'::text, 'BUILT_IN'::text), ('miaoda/miaoda-model-auto'::text, 'BUILT_IN'::text), ('miaoda/miaoda-model-flash'::text, 'BUILT_IN'::text), ('miaoda/miaoda-auto-multimodal'::text, 'BUILT_IN'::text), ('miaoda/glm-5.3'::text, 'BUILT_IN'::text), ('dli/gpt-5.6-sol'::text, 'CUSTOM'::text), ('m3probe/minimax-m3'::text, 'CUSTOM'::text))) IS TRUE) AND jsonb_typeof(execution_model_json::jsonb -> 'displayName'::text) = 'string'::text AND (execution_model_json::jsonb ->> 'displayName'::text) <> ''::text AND jsonb_typeof(execution_model_json::jsonb -> 'settingsRevision'::text) = 'number'::text AND ((execution_model_json::jsonb ->> 'settingsRevision'::text)::numeric) >= 0::numeric AND jsonb_typeof(execution_model_json::jsonb -> 'selectedAt'::text) = 'string'::text) OR subject_kind::text = 'DERIVED_SUMMARY'::text AND work_item_id IS NULL AND matter_id IS NULL AND matter_revision_id IS NULL AND document_version_id IS NULL AND summary_id IS NOT NULL AND action_type::text = 'OPENCLAW_DERIVED_SUMMARY'::text AND input_revision IS NOT NULL AND base_revision IS NOT NULL);
COMMIT;
